// French for what the servers send back and the page shows: the local server (askeden/src/chat/*.ts,
// src/verify/labels.ts, EVES and research status lines, route rationale and notes) and the askeden.com
// Worker (JARVIS V1/site/src: eden/*, accounts/*, edu/*, worker.js). Errors arrive as JSON { error } or
// SSE { message } and are shown as toasts and notices; the servers keep writing English. See i18n.js.
// No imports here (this loads during i18n.js's top-level await).

const NB = ' ';
/** French spacing: a no-break space before : ; ! ? and inside « ». */
const fr = (s) => String(s).replace(/ ([:;!?»])/g, `${NB}$1`).replace(/« /g, `«${NB}`);

