/* ---------- patterns (anchored) ---------- */

const EFFORT = { none: 'aucun', minimal: 'minimal', low: 'faible', medium: 'moyen', high: 'élevé', xhigh: 'très élevé', max: 'maximal' };
const effortWord = (w) => EFFORT[String(w).toLowerCase()] || w;
const COMPLEXITY = { simple: 'simple', moderate: 'modérée', complex: 'complexe', expert: 'experte' };
const num = (s) => String(s).replace(/(\d),(\d{3})/g, `$1${NB}$2`).replace(/(\d)\.(\d)/g, '$1,$2');
const pl = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`;
const cheaperFr = (s) => String(s).replace(/^([\d.]+)× cheaper$/, (_m, r) => `${num(r)}× moins cher`).replace(/^(\d+)% cheaper$/, `$1${NB}% moins cher`);

